<script setup lang="tsx">
import { onMounted, ref } from 'vue'; import { NButton, NTag } from 'naive-ui'; import { useRouterPush } from '@/hooks/common/router'; import { fetchApps } from '@/service/api'; import type { AndroidApp } from '@/service/api/app-publish';
const { routerPush } = useRouterPush(false); const rows = ref<AndroidApp[]>([]); const loading = ref(false); const keyword = ref(''); const total = ref(0); const page = ref(1);
const columns = [{ title: '应用', key: 'appName', render: (row: AndroidApp) => <div class="app-cell"><b>{row.appName}</b><code>{row.packageName}</code></div> }, { title: '状态', key: 'status', width: 110, render: (row: AndroidApp) => <NTag type={row.status === 'ENABLED' ? 'success' : 'default'} round>{row.status === 'ENABLED' ? '运行中' : '已停用'}</NTag> }, { title: '最近更新', key: 'updatedAt', width: 180, render: (row: AndroidApp) => new Date(row.updatedAt).toLocaleString() }, { title: '', key: 'action', width: 110, render: (row: AndroidApp) => <NButton text type="primary" onClick={() => routerPush(`/release/apps-detail/${row.id}`)}>版本档案 →</NButton> }];
async function load() { loading.value = true; const result = await fetchApps({ page: page.value, size: 20, keyword: keyword.value || undefined }); if (!result.error) { rows.value = result.data.records; total.value = result.data.total; } loading.value = false; } onMounted(load);
</script>
<template><NSpace vertical :size="16"><NCard :bordered="false"><div class="page-head"><div><p>APP INVENTORY</p><h2>应用列表</h2><span>包名是应用的唯一身份，上传后自动归档。</span></div><NButton type="primary" @click="routerPush('/release/upload')">上传 APK</NButton></div></NCard><NCard :bordered="false"><div class="toolbar"><NInput v-model:value="keyword" clearable placeholder="搜索应用名称或包名" @keyup.enter="load"/><NButton @click="load">查询</NButton></div><NDataTable :columns="columns" :data="rows" :loading="loading" :row-key="row => row.id"/><NPagination v-if="total > 20" v-model:page="page" class="pager" :item-count="total" :page-size="20" @update:page="load"/></NCard></NSpace></template>
<style scoped>.page-head{display:flex;align-items:flex-end;justify-content:space-between}.page-head p{margin:0;color:#6a8676;font:700 10px ui-monospace,monospace;letter-spacing:.16em}.page-head h2{margin:5px 0;font-size:26px}.page-head span{color:#7c8981}.toolbar{display:flex;gap:10px;margin-bottom:16px}.toolbar .n-input{max-width:360px}.pager{justify-content:flex-end;margin-top:18px}:deep(.app-cell){display:flex;flex-direction:column;gap:3px}:deep(.app-cell code){color:#849088;font-size:12px}</style>
